onClick:
{{(() => {
     if (!ItemNameInput.text ) {
       showAlert("Въведете име на артикул", "error");
       return;
     }

     // Weight and L×W×H per unit are required (Ico, 2026-10-02): the товарителница sums
     // them, and the console shows them on every product line. Comma or point both work.
     const num = (w) => { const v = Number(String(w.text || "").trim().replace(",", ".")); return v > 0 ? v : null; };
     const weight = num(ItemWeightInput), length = num(ItemLengthInput), width = num(ItemWidthInput), height = num(ItemHeightInput);
     if (weight === null || length === null || width === null || height === null) {
       showAlert("Въведете тегло (кг) и размери (см) на артикула - дължина, ширина и височина", "error");
       return;
     }

     // What one parcel may be (BUSINESS.md: 90×90×90 cm, 20 kg). Anything bigger is a
     // phone call, not an order (Ico, 2026-10-06): the office checks whether it can be
     // taken and at what price. The server refuses the same way, so the Excel upload
     // cannot slip one through either.
     const MAX_KG = 20, MAX_CM = 90;
     if (weight > MAX_KG || length > MAX_CM || width > MAX_CM || height > MAX_CM) {
       showAlert(appsmith.store.bo_lang === 'en'
         ? "This parcel is over our limit of 90×90×90 cm and 20 kg. Please call us on +359 88 286 8723 so we can check whether we can take it and at what price."
         : "Пратката надвишава максималните 90×90×90 см и 20 кг. Обадете ни се на +359 88 286 8723, за да проверим дали можем да я вземем и на каква цена.", "error");
       return;
     }

     const currentItems = appsmith.store.newOrderItems || [];
     const newItem = {
       name: ItemNameInput.text,
       sku: ItemSkuInput.text || "",
       quantity: parseInt(ItemQuantityInput.text) || 1,
       weight_kg: weight,
       length_cm: length,
       width_cm: width,
       height_cm: height
     };

     storeValue('newOrderItems', [...currentItems, newItem]);

     // Clear inputs
     ItemNameInput.setValue('');
     ItemSkuInput.setValue('');
     ItemQuantityInput.setValue('1');
     ItemWeightInput.setValue('');
     ItemLengthInput.setValue('');
     ItemWidthInput.setValue('');
     ItemHeightInput.setValue('');

     showAlert("Артикулът е добавен", "success");
   })()}}
